{
  "groups": [
    {
      "group_id": "vulnerable_variable_rate",
      "rule": "rate_type == 'variable' and credit_score_band in ['below_600', '600_659']",
      "rationale": "Borrowers with variable rates and lower credit scores are highly sensitive to payment shock and default risk."
    },
    {
      "group_id": "high_equity_renewals",
      "rule": "origination_year <= 2019 and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers who locked in low rates years ago face significant payment increases upon renewal."
    },
    {
      "group_id": "wealthy_active_savers",
      "rule": "has_investments == True and td_deposits_3m_change_cad > 0",
      "rationale": "Affluent clients with growing liquid assets demonstrate high retention potential through proactive financial advice."
    },
    {
      "group_id": "distressed_recent_entrants",
      "rule": "origination_year >= 2022 and credit_utilization_pct > 45.0",
      "rationale": "Recent buyers with high revolving debt are at risk of attrition due to financial strain from rising rates."
    },
    {
      "group_id": "stable_long_tenure",
      "rule": "td_tenure_months > 90 and credit_score_band == '720_plus'",
      "rationale": "Long-tenured, prime credit customers are the most loyal but require competitive loyalty pricing to prevent churn."
    },
    {
      "group_id": "event_driven_movers",
      "rule": "life_event_6m == True and life_event_type != 'none'",
      "rationale": "Major life transitions trigger mortgage reassessment and provide specific touchpoints for tailored retention offers."
    },
    {
      "group_id": "cash_constrained_families",
      "rule": "n_children >= 3 and has_savings == False",
      "rationale": "Large households without a savings buffer are highly susceptible to interest rate hikes affecting their monthly disposable income."
    }
  ]
}
